const aIAssistantSweepTurns = `-- name: AIAssistantSweepTurns :many
SELECT t.id, t.thread_id, h.workspace_id FROM ai_assistant_turns t JOIN ai_assistant_threads h ON h.id = t.thread_id
WHERE (t.state = 'answering' AND NOT EXISTS (SELECT 1 FROM ai_assistant_slots s WHERE s.turn_id = t.id AND s.expires_at > $1))
   OR (t.state = 'queued' AND coalesce(t.queued_at, t.created_at) < $2::timestamptz)
ORDER BY t.created_at LIMIT 100
`

type AIAssistantSweepTurnsParams struct {
	Now          time.Time `json:"now"`
	QueuedBefore time.Time `json:"queuedBefore"`
}

type AIAssistantSweepTurnsRow struct {
	ID          uuid.UUID `json:"id"`
	ThreadID    uuid.UUID `json:"threadId"`
	WorkspaceID uuid.UUID `json:"workspaceId"`
}

// Turns no worker answers: answering without a live slot (the worker died
// or lost its lease), or queued since before @queued_before (their job is
// gone).
func (q *Queries) AIAssistantSweepTurns(ctx context.Context, arg AIAssistantSweepTurnsParams) ([]AIAssistantSweepTurnsRow, error) {
	rows, err := q.db.Query(ctx, aIAssistantSweepTurns, arg.Now, arg.QueuedBefore)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []AIAssistantSweepTurnsRow{}
	for rows.Next() {
		var i AIAssistantSweepTurnsRow
		if err := rows.Scan(&i.ID, &i.ThreadID, &i.WorkspaceID); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

